select d.* , c.name as categoryName from dish d left outer join category c on d.category_id = c.id
and d.name like concat('%',#{name},'%')
and d.category_id = #{categoryId}
and d.status = #{status}
order by d.create_time desc

mapper.update:
update dish
name = #{name}, category_id = #{categoryId}, price = #{price}, image = #{image}, description = #{description}, status = #{status}, stock = #{stock}, update_time = #{updateTime}, update_user = #{updateUser},
where id = #{id}

update dish
set stock = stock - #{quantity}
where id = #{dishId}
  and status = 1
  and stock >= #{quantity}

update dish
set stock = (select coalesce(sum(stock), 0) from product_sku where dish_id = #{dishId} and status = 1)
where id = #{dishId}

